# qx2_cos_sim :: ([1, 0], [1, 0])
def qx2_cos_sim(a, b):
    an = sum(x * x for x in a) ** 0.5
    bn = sum(x * x for x in b) ** 0.5
    if an == 0 or bn == 0:
        return 0.0
    return sum(x * y for x, y in zip(a, b)) / (an * bn)

if __name__ == '__main__':
    print(qx2_cos_sim(([1, 0], [1, 0])))

